import numpy as np,cv2
from PIL import Image
z=np.load('/app/output/stroke_debug.npz'); t0=np.array(Image.open('/app/target.png')).mean(2)<128
ys,xs=np.where(t0); y0=max(0,ys.min()-50);y1=min(1024,ys.max()+51);x0=max(0,xs.min()-50);x1=min(1024,xs.max()+51)
t=t0[y0:y1,x0:x1]
base=[(z[f'mask_{i}'][y0:y1,x0:x1]>=128).astype(np.uint8) for i in range(1,17)]
def transform(a,r,dx,dy):
 if r>0:
  k=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*r+1,2*r+1));a=cv2.dilate(a,k)
 elif r<0:
  k=cv2.getStructuringElement(cv2.MORPH_ELLIPSE,(2*(-r)+1,2*(-r)+1));a=cv2.erode(a,k)
 h,w=a.shape;o=np.zeros_like(a);xA=max(0,dx);xB=min(w,w+dx);yA=max(0,dy);yB=min(h,h+dy)
 if xA<xB and yA<yB:o[yA:yB,xA:xB]=a[max(0,-dy):min(h,h-dy),max(0,-dx):min(w,w-dx)]
 return o
def score(ms):
 p=np.logical_or.reduce(ms).astype(bool);return (p&t).sum()/((p|t).sum())
ms=base.copy(); params=[[0,0,0] for _ in ms]
for sweep in range(2):
 for i in range(16):
  rest=np.logical_or.reduce(ms[:i]+ms[i+1:]);
  best=(score(ms),0,0,0,ms[i])
  for r in range(-2,3):
   for dy in range(-2,3):
    for dx in range(-2,3):
     q=transform(base[i],r,params[i][1]+dx,params[i][2]+dy)
     cand=rest|q; val=(cand.astype(bool)&t).sum()/((cand.astype(bool)|t).sum())
     if val>best[0]:best=(val,r,params[i][1]+dx,params[i][2]+dy,q)
  ms[i]=best[4];params[i]=[best[1],best[2],best[3]]
 print('sweep',sweep,'iou',score(ms))
print('params radius/dx/dy',params)
cur=[(2,-9),(4,2),(8,1),(8,2),(9,-4),(1,-2),(2,2),(12,-24),(12,9),(1,1),(-2,-1),(7,3),(12,7),(25,1),(12,2),(-2,2)]
print('abs shifts',[(a[0],a[1]+b[1],a[2]+b[2]) for a,b in zip(params,cur)])
